36: function project(x,y,z){let a=player.angle,fx=Math.sin(a),fz=Math.cos(a),cx=player.x-fx*4.25,cz=player.z-fz*4.25,cy=2.65;let dx=x-cx,dy=y-cy,dz=z-cz;let pitch=.18,forward=dx*Math.cos(pitch)*fx+dy*(-Math.sin(pitch))+dz*Math.cos(pitch)*fz;let up=dx*(-Math.sin(pitch)*fx)+dy*Math.cos(pitch)+dz*(-Math.sin(pitch)*fz);let right=dx*fz-dz*fx;let focal=Math.min(W,H)*.92;return {x:W/2+right*focal/Math.max(.15,forward),y:H*.43-up*focal/Math.max(.15,forward),d:forward};}
