42: function drawWall(w){let dx=w.x2-w.x1,dz=w.z2-w.z1,len=Math.hypot(dx,dz),nx=-dz/len*.10,nz=dx/len*.10;let base=[[w.x1,0,w.z1],[w.x2,0,w.z2],[w.x2,w.h,w.z2],[w.x1,w.h,w.z1]];let mid=project((w.x1+w.x2)/2,w.h/2,(w.z1+w.z2)/2);if(mid.d<.2)return;let shade=w.kind==='outer'?'#222b27':'#2a302b';poly(base,shade);poly([[w.x1,0,w.z1],[w.x2,0,w.z2],[w.x2+nx,0,w.z2+nz],[w.x1+nx,0,w.z1+nz]],'#111815');poly([[w.x1,w.h,w.z1],[w.x2,w.h,w.z2],[w.x2+nx,w.h,w.z2+nz],[w.x1+nx,w.h,w.z1+nz]],'#465047');
