47: function drawZombie(z){if(z.hp<=0)return;let dx=z.x-player.x,dz=z.z-player.z,dist=Math.hypot(dx,dz);if(dist>19)return;let p=project(z.x,0,z.z),head=project(z.x,.34,z.z),top=project(z.x,1.72,z.z);if(p.d<=.2||top.y>H+200||top.y<-500)return;let scale=clamp(58/p.d,5,80);let sway=Math.sin(z.walk)*scale*.04;ctx.save();ctx.translate(p.x+sway,p.y);ctx.globalAlpha=.94;
