52: ctx.fillStyle=z.awake?'#56604f':'#39443a';ctx.beginPath();ctx.moveTo(-scale*.29,-scale*.55);ctx.lineTo(-scale*.25,-scale*1.35);ctx.lineTo(-scale*.12,-scale*1.48);ctx.lineTo(scale*.18,-scale*1.4);ctx.lineTo(scale*.32,-scale*.56);ctx.lineTo(scale*.2,-scale*.45);ctx.lineTo(-scale*.25,-scale*.45);ctx.fill();
