67: function render(){drawAtmosphere();drawFloor();let renderables=[];walls.forEach(w=>{let p=project((w.x1+w.x2)/2,w.h/2,(w.z1+w.z2)/2);renderables.push({d:p.d,draw:()=>drawWall(w)})});props.forEach(o=>{let p=project(o.x,o.h/2,o.z);renderables.push({d:p.d,draw:()=>drawProp(o)})});zombies.forEach(z=>{let p=project(z.x,0,z.z);renderables.push({d:p.d,draw:()=>drawZombie(z)})});renderables.sort((a,b)=>b.d-a.d).forEach(o=>o.draw());drawPlayer();drawLight();if(shake>0){ctx.fillStyle=`rgba(255,255,255,${shake*.025})`;ctx.fillRect(0,0,W,H);shake=Math.max(0,shake-.1)}
