71: function move(dt){let fw=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);if(window.touchMove){fw=window.touchMove.y;side=window.touchMove.x}let mag=Math.hypot(fw,side);if(mag){fw/=Math.max(1,mag);side/=Math.max(1,mag);let speed=keys.ShiftLeft?4.1:2.6;let vx=Math.sin(player.angle)*fw+Math.cos(player.angle)*side,vz=Math.cos(player.angle)*fw-Math.sin(player.angle)*side;let nx=player.x+vx*speed*dt,nz=player.z+vz*speed*dt;if(!collides(nx,player.z))player.x=nx;if(!collides(player.x,nz))player.z=nz;walk+=dt*8;noise=Math.max(noise,keys.ShiftLeft?1:.4)}else noise=Math.max(0,noise-dt*.42);player.focus=clamp(player.focus+dt*(mag?-.8:3),0,100);}
72: function collides(x,z){if(x<-10.35||x>10.35||z<-12.35||z>14.2||(z>12.35&&Math.abs(x)>1.2))return true;for(let w of walls){let dx=w.x2-w.x1,dz=w.z2-w.z1,l2=dx*dx+dz*dz,t=clamp(((x-w.x1)*dx+(z-w.z1)*dz)/l2,0,1),qx=w.x1+t*dx,qz=w.z1+t*dz;if(Math.hypot(x-qx,z-qz)<.48)return true}for(let o of props)if(Math.abs(x-o.x)<o.w/2+.38&&Math.abs(z-o.z)<o.d/2+.38)return true;return false}
