function drawPlayer(){// third-person officer, anchored just below center
let a=player.angle,sideX=Math.cos(a)*.58,sideZ=-Math.sin(a)*.58;let px=player.x, pz=player.z;let foot=project(px,0,pz),head=project(px,1.75,pz);let size=clamp(68/foot.d,22,55);ctx.save();ctx.translate(foot.x,foot.y);if(player.stealth)ctx.scale(1,.82);ctx.fillStyle='#040705aa';ctx.beginPath();ctx.ellipse(0,0,size*.48,size*.14,0,0,Math.PI*2);ctx.fill();
// legs
ctx.fillStyle='#151b19';ctx.fillRect(-size*.23,-size*.57,size*.18,size*.53);ctx.fillRect(size*.05,-size*.57,size*.18,size*.53);
ctx.fillStyle='#303c38';ctx.beginPath();ctx.moveTo(-size*.32,-size*.56);ctx.lineTo(-size*.28,-size*1.34);ctx.lineTo(-size*.15,-size*1.48);ctx.lineTo(size*.17,-size*1.43);ctx.lineTo(size*.3,-size*.55);ctx.closePath();ctx.fill();ctx.fillStyle='#68715f';ctx.fillRect(-size*.19,-size*1.13,size*.38,size*.075);
ctx.fillStyle='#9b9c84';ctx.beginPath();ctx.ellipse(0,-size*1.58,size*.18,size*.22,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#212824';ctx.fillRect(-size*.22,-size*1.75,size*.44,size*.1);ctx.fillStyle='#141a18';ctx.fillRect(-size*.15,-size*1.61,size*.3,size*.08);
// pistol to right, barrel toward facing
ctx.strokeStyle='#131816';ctx.lineWidth=size*.09;ctx.beginPath();ctx.moveTo(size*.12,-size*1.04);ctx.lineTo(size*.43,-size*1.13);ctx.lineTo(size*.57,-size*1.13);ctx.stroke();ctx.restore();}

