ctx.strokeStyle='#2c2f39';ctx.lineWidth=Math.max(1,size*.018);ctx.beginPath();ctx.moveTo(-size*.3,-size*.62);ctx.lineTo(-size*.27,-size*1.28);ctx.moveTo(size*.29,-size*.62);ctx.lineTo(size*.27,-size*1.25);ctx.moveTo(0,-size*.5);ctx.lineTo(0,-size*1.2);ctx.stroke();
