if(player.weapon===1){ctx.lineWidth=size*.12;ctx.beginPath();ctx.moveTo(size*.1,-size*1.06);ctx.lineTo(size*.34,-size*1.12);ctx.lineTo(size*.68,-size*1.12);ctx.stroke();ctx.fillStyle='#39281c';ctx.fillRect(size*.3,-size*1.14,size*.24,size*.08)}
else if(player.weapon===2){ctx.lineWidth=size*.08;ctx.beginPath();ctx.moveTo(size*.1,-size*1.06);ctx.lineTo(size*.5,-size*1.14);ctx.lineTo(size*.82,-size*1.14);ctx.stroke();ctx.fillStyle='#1a1d20';ctx.fillRect(size*.34,-size*1.18,size*.27,size*.075);ctx.fillStyle='#3b3f42';ctx.fillRect(size*.44,-size*1.26,size*.12,size*.07)}
else{ctx.beginPath();ctx.moveTo(size*.12,-size*1.04);ctx.lineTo(size*.43,-size*1.13);ctx.lineTo(size*.57,-size*1.13);ctx.stroke()}
ctx.restore();}

